const ruleset = body.ruleset;
const options = body.options || {};
const pluginContext = body.plugin_context || {};

const errors = [];
if (!items || !Array.isArray(items) || items.length === 0) {
  errors.push('items (array) is required');
}
if (!ruleset || typeof ruleset !== 'string') {
  errors.push('ruleset (string) is required');
}

// Check if LLM-based ruleset needs API key
const llmRulesets = ['cuisine_tags', 'torah_topics'];
if (llmRulesets.includes(ruleset) && !pluginContext.api_keys?.anthropic) {
  errors.push('plugin_context.api_keys.anthropic is required for LLM rulesets');
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  };
}

// Determine ruleset type
const jsonRulesets = ['allergens_inco'];
const rulesetType = jsonRulesets.includes(ruleset) ? 'json_mapping' : 'llm_classify';

return {
  json: {
    valid: true,
    startTime: Date.now(),
    items: items.map(i => typeof i === 'string' ? i.toLowerCase().trim() : String(i).toLowerCase().trim()),
    items_original: items,
    ruleset: ruleset,
    ruleset_type: rulesetType,
    options: {
      include_possible: options.include_possible !== false,
      language: options.language || 'fr'
    },
    plugin_context: pluginContext,
    api_key: pluginContext.api_keys?.anthropic
