// Get ruleset data
let rulesetData;
if (ruleset === 'allergens_inco') {
  rulesetData = allergensInco;
} else {
  return {
    json: {
      success: false,
      error: {
        code: 400,
        message: `Unknown JSON ruleset: ${ruleset}`,
        status: 'BAD_REQUEST'
      }
    }
  };
}

// Detection logic
const confirmed = [];
const possibleTraces = [];
const warnings = [];
const confirmedMap = new Map(); // category -> sources
const tracesMap = new Map(); // category -> sources

// Process each item
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const itemOriginal = itemsOriginal[i];

  // Check each category
  for (const category of rulesetData.categories) {
    // Check exclusions first
    const exclusions = category.exclusions || [];
    const isExcluded = exclusions.some(ex => item.includes(ex.toLowerCase()));
    if (isExcluded) continue;

    // Check confirmed keywords
    const isConfirmed = category.keywords.some(kw => {
      const kwLower = kw.toLowerCase();
      return item.includes(kwLower) || kwLower.includes(item);
    });

    if (isConfirmed) {
      if (!confirmedMap.has(category.id)) {
        confirmedMap.set(category.id, { category, sources: [] });
      }
      confirmedMap.get(category.id).sources.push(itemOriginal);
    }

    // Check traces keywords (only if include_possible and not already confirmed for this item)
    if (includePossible && !isConfirmed) {
      const isTrace = category.traces_keywords.some(kw => {
        const kwLower = kw.toLowerCase();
        return item.includes(kwLower) || kwLower.includes(item);
      });

      if (isTrace) {
        if (!tracesMap.has(category.id)) {
          tracesMap.set(category.id, { category, sources: [] });
        }
        tracesMap.get(category.id).sources.push(itemOriginal);
      }
    }
  }

  // Check warnings
  for (const warning of rulesetData.warnings) {
    const regex = new RegExp(warning.pattern.toLowerCase());
    if (regex.test(item) && !warnings.includes(warning.message)) {
      warnings.push(warning.message);
    }
  }
}

// Build confirmed list
for (const [id, data] of confirmedMap) {
  confirmed.push({
    type: data.category.id,
    label: data.category.label,
    icon: data.category.icon,
    sources: [...new Set(data.sources)] // dedupe
  });
}

// Build traces list (exclude already confirmed)
for (const [id, data] of tracesMap) {
  if (!confirmedMap.has(id)) {
    possibleTraces.push({
      type: data.category.id,
      label: data.category.label,
      icon: data.category.icon,
      sources: [...new Set(data.sources)],
      reason: 'Traces possibles'
    });
  }
}

// Build display strings
const confirmedLabels = confirmed.map(c => `${c.icon} ${c.label}`).join(', ');
const tracesLabels = possibleTraces.map(t => t.label).join(', ');

let displayShort = '';
if (confirmed.length > 0) {
  displayShort = `Allergènes : ${confirmedLabels}`;
}
if (possibleTraces.length > 0) {
  displayShort += (displayShort ? ' | ' : '') + `Traces possibles : ${tracesLabels}`;
}
if (!displayShort) {
  displayShort = 'Aucun allergène INCO détecté';
}

return {
  json: {
    success: true,
    detected: {
      confirmed: confirmed,
      possible_traces: possibleTraces
    },
    warnings: warnings,
    display: {
      short: displayShort,
      html: displayShort.replace('Allergènes :', '<strong>Allergènes :</strong>').replace('Traces possibles :', '<em>Traces possibles :</em>')
    },
    inco_compliant: true,
    meta: {
      ruleset: ruleset,
      ruleset_type: 'json_mapping',
      items_count: items.length,
      confirmed_count: confirmed.length,
      traces_count: possibleTraces.length
    },
    _trace: {
      llm_response: null,
      ruleset: ruleset,
      items_processed: items.length,
      latency_ms: Date.now() - (input.startTime || Date.now())
    }
  }
};

