const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const statusCode = input.statusCode || 200;

// Handle LLM API error
if (statusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: input.body?.error?.message || 'LLM API error',
        status: 'LLM_ERROR'
      }
    }
  };
}

// Extract LLM response content
const content = input.body?.content?.[0]?.text || '';

// Parse JSON from LLM response
let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse LLM response: ' + e.message,
        status: 'PARSE_ERROR'
      }
    }
  };
}

const detected = parsed.detected || { confirmed: [], possible_traces: [] };
const warnings = parsed.warnings || [];

// Build display
const confirmedLabels = (detected.confirmed || []).map(c => c.label).join(', ');
const tracesLabels = (detected.possible_traces || []).map(t => t.label).join(', ');

let displayShort = '';
if (detected.confirmed?.length > 0) {
  displayShort = `Catégories : ${confirmedLabels}`;
}
if (detected.possible_traces?.length > 0) {
  displayShort += (displayShort ? ' | ' : '') + `Possibles : ${tracesLabels}`;
}
if (!displayShort) {
  displayShort = 'Aucune catégorie détectée';
}

return {
  json: {
    success: true,
    detected: detected,
    warnings: warnings,
    display: {
      short: displayShort,
      html: displayShort
    },
    meta: {
      ruleset: prevData.ruleset,
      ruleset_type: 'llm_classify',
      provider: 'anthropic',
      model: prevData.plugin_context.llm_model || 'claude-3-haiku-20240307',
      items_count: prevData.items.length
    },
    _trace: {
      llm_response: input.body?.content || [],
      ruleset: prevData.ruleset,
      items_processed: prevData.items?.length || 0,
      latency_ms: Date.now() - (prevData.startTime || Date.now())
    }
  }
};
